p.name = 'HS24'; p.family = 'hs'; p.n = 2; p.m = 3;
p.x0 = [1.0; 0.5];
p.xl = [0.0; 0.0]; p.xu = [Inf; Inf];
p.cl = [0.0; 0.0; 0.0]; p.cu = [Inf; Inf; Inf];
