function f = HS24_f(x)
f = sqrt(3)*x(2).^3.*((x(1) - 3).^2 - 9)/81;
end

function g = HS24_g(x)
g = zeros(2, 1);
g(1) = sqrt(3)*x(2).^3.*(2*x(1) - 6)/81;
g(2) = sqrt(3)*x(2).^2.*((x(1) - 3).^2 - 9)/27;
end

function c = HS24_c(x)
c = zeros(3, 1);
c(1) = sqrt(3)*x(1)/3 - x(2);
c(2) = x(1) + sqrt(3)*x(2);
c(3) = -x(1) - sqrt(3)*x(2) + 6;
end

function J = HS24_J(x)
J = zeros(3, 2);
J(1, 1) = sqrt(3)/3;
J(1, 2) = -1;
J(2, 1) = 1;
J(2, 2) = sqrt(3);
J(3, 1) = -1;
J(3, 2) = -sqrt(3);
end
